<?php
declare(strict_types=1);
require_once __DIR__.'/../engine.php';require_once __DIR__.'/goal.php';require_once __DIR__.'/../preparation.php';
function preparationAction(string $action,array $input):array{
 $c=permit(['owner','foreman','technologist','chief']);$o=orderRecord(textField($input,'order_id',32,true));$o['route']=decode($o['route']);$o['preparation_route']=productionPreparationRoute($o['route']);
 if($action==='preparation_open')return ['preparation'=>preparationRecord($c,$o)??['id'=>null,'revision'=>0,'state'=>preparationDefault($c,$o)],'order_revision'=>(int)$o['revision'],'storage_available'=>preparationAvailable()];
 if(!preparationAvailable())fail('Импортируйте database/update_20261023.sql для отдельной комплектации.',503);
 return command($action,$input,function(array $c)use($input){$o=orderRecord(textField($input,'order_id',32,true),true);$o['route']=decode($o['route']);$record=preparationRecord($c,$o);checkRevision($record['revision']??0,$input);if((int)($input['order_revision']??-1)!==(int)$o['revision'])fail('Цель изменилась. Откройте комплектацию заново.',409);$state=preparationNormalize($input['state']??[],$c,$o);
  $used=[];foreach(rows("SELECT operation_id,released,planning_meta FROM tasks WHERE company_id=? AND order_id=? AND state<>'cancelled'",[$c['id'],$o['id']]) as $t){$meta=decode($t['planning_meta']??null);$variant=$meta['variant_id']??'variant-main';$used[$variant][$t['operation_id']]=($used[$variant][$t['operation_id']]??0)+(int)$t['released'];}foreach($state['items'] as $v)if($v['ready']<max([0,...array_values($used[$v['id']]??[])]))fail('Нельзя уменьшить подтверждённую комплектацию ниже уже запущенного количества');
  $id=$record['id']??uid();$rev=($record['revision']??0)+1;if($record)query('UPDATE order_preparations SET state_json=?,revision=?,actor_id=? WHERE id=? AND company_id=?',[j($state),$rev,$_SESSION['user_id'],$id,$c['id']]);else query('INSERT INTO order_preparations (id,company_id,order_id,revision,state_json,actor_id) VALUES (?,?,?,?,?,?)',[$id,$c['id'],$o['id'],$rev,j($state),$_SESSION['user_id']]);query('INSERT INTO preparation_revisions (id,preparation_id,company_id,revision,state_json,actor_id) VALUES (?,?,?,?,?,?)',[uid(),$id,$c['id'],$rev,j($state),$_SESSION['user_id']]);
  $expenses=array_values(array_filter(decode($o['expenses']),fn($e)=>($e['id']??'')!=='preparation-cost'));if($state['cost_mode']==='amount')$expenses[]=['id'=>'preparation-cost','name'=>'Подготовка и комплектация · '.$state['source'],'kind'=>'direct','cents'=>$state['cost_cents']];query('UPDATE orders SET expenses=?,revision=revision+1 WHERE id=? AND company_id=?',[j($expenses),$o['id'],$c['id']]);audit('preparation_saved',['order_id'=>$o['id'],'revision'=>$rev]);return ['saved'=>true,'revision'=>$rev,'order_revision'=>(int)$o['revision']+1];
 });
}
